import ipaddress
import requests
def task_func(ip_range, timeout):
    # Validate the IP range
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except Exception:
        raise ValueError(f"Invalid IP range: {ip_range}")

    active_ips = []

    # Iterate through all usable host IPs in the network
    for ip in network.hosts():
        ip_str = str(ip)
        try:
            # Send HTTP GET request to the IP address
            response = requests.get(f"http://{ip_str}", timeout=timeout)

            # Check if the response status code is 200
            if response.status_code == 200:
                active_ips.append(ip_str)
        except Exception:
            # Ignore any request failures and continue to the next IP
            continue

    return active_ips

